/**
 * Campo de código de 6 dígitos (componente <x-otp-input>), usado na ativação do 2FA e na verificação do login.
 * onChange(code) é chamado a cada alteração; onEnter(code), se informado, substitui o Enter padrão do formulário.
 */
function bindOtpInput(selector, onChange, onEnter = null) {
    if (!elementExists(selector)) {
        return;
    }

    const $inputs = $(selector + ' input');

    $inputs.on('focus', function() {
        this.select();
    });

    $inputs.on('input', function() {
        const index = $inputs.index(this);
        const digits = this.value.replace(/\D/g, '');

        // Autopreenchimento do teclado (one-time-code) entrega os 6 dígitos de uma vez
        if (digits.length > 1) {
            fillOtp(selector, digits, index);
        } else {
            this.value = digits;

            if (digits) {
                $inputs.eq(index + 1).trigger('focus');
            }
        }

        onOtpChange(selector, onChange);
    });

    $inputs.on('paste', function(e) {
        e.preventDefault();

        const text = (e.originalEvent.clipboardData || window.clipboardData).getData('text');
        fillOtp(selector, text.replace(/\D/g, ''), 0);
        onOtpChange(selector, onChange);
    });

    $inputs.on('keydown', function(e) {
        const index = $inputs.index(this);

        if (e.key === 'Backspace' && !this.value && index > 0) {
            e.preventDefault();
            $inputs.eq(index - 1).val('').trigger('focus');
            onOtpChange(selector, onChange);
        } else if (e.key === 'ArrowLeft' && index > 0) {
            e.preventDefault();
            $inputs.eq(index - 1).trigger('focus');
        } else if (e.key === 'ArrowRight' && index < $inputs.length - 1) {
            e.preventDefault();
            $inputs.eq(index + 1).trigger('focus');
        } else if (e.key === 'Enter' && isFunction(onEnter)) {
            e.preventDefault();
            onEnter(getOtpValue(selector));
        }
    });
}

function fillOtp(selector, digits, start) {
    const $inputs = $(selector + ' input');

    digits.slice(0, $inputs.length - start).split('').forEach(function(digit, i) {
        $inputs.eq(start + i).val(digit);
    });

    $inputs.eq(Math.min(start + digits.length, $inputs.length - 1)).trigger('focus');
}

function onOtpChange(selector, onChange) {
    clearOtpError(selector);

    if (isFunction(onChange)) {
        onChange(getOtpValue(selector));
    }
}

function getOtpValue(selector) {
    return $(selector + ' input').map(function() {
        return this.value;
    }).get().join('');
}

function focusOtp(selector) {
    $(selector + ' input').first().trigger('focus');
}

function clearOtp(selector) {
    $(selector + ' input').val('');
    clearOtpError(selector);
}

function clearOtpError(selector) {
    $(selector).removeClass('is-invalid');
    $(selector + '-error').addClass('d-none').text('');
}

// Destaca o erro, limpa os dígitos e devolve o foco ao primeiro campo
function showOtpError(selector, message) {
    const $otp = $(selector).addClass('is-invalid is-shake');
    setTimeout(function() { $otp.removeClass('is-shake'); }, 400);

    $(selector + ' input').val('');
    $(selector + '-error').text(message).removeClass('d-none');
    focusOtp(selector);
}

$(document).ready(function() {
    bindTwoFactorWizard();
    bindTwoFactorRecoveryCodes();
    bindTwoFactorManage();
});

let twoFactorRecoveryCodes = [];
let twoFactorConfirming = false;

function twoFactorRequest(url, type, data = {}) {
    return $.ajax({
        url: url,
        type: type,
        dataType: 'json',
        data: data,
        headers: {
            'X-CSRF-TOKEN': $('meta[name="csrf-token"]').attr('content')
        },
    });
}

function twoFactorErrorMessage(jqXHR) {
    const json = jqXHR.responseJSON || {};

    if (json.message) {
        return json.message;
    }

    const first = Object.values(json)[0];

    return Array.isArray(first) ? first[0] : 'Não foi possível concluir a operação. Tente novamente.';
}

// Pede o código do app (ou de recuperação) antes de ações sensíveis; também usado em medical-records.js.
function promptTwoFactorReauth(options) {
    $('.wrapper').addClass('d-none');

    return appDialog({
        tone: 'lock',
        title: options.title,
        text: options.text,
        content: '<label for="two-factor-code" class="app-dialog-label">Código de verificação</label>' +
            // Aceita os 6 dígitos do aplicativo ou o código de recuperação (xxxxx-xxxxx).
            '<input id="two-factor-code" class="form-control text-center" maxlength="11" autocomplete="one-time-code" ' +
                'autocapitalize="off" autocorrect="off" spellcheck="false" placeholder="123456 ou xxxxx-xxxxx">',
        confirmText: options.confirmText,
        cancelText: 'Cancelar',
        allowOutsideClick: false,
        didOpen: function(popup) {
            const input = popup.querySelector('#two-factor-code');

            input.addEventListener('input', () => Swal.resetValidationMessage());
            input.addEventListener('keydown', function(event) {
                if (event.key === 'Enter') {
                    event.preventDefault();
                    Swal.clickConfirm();
                }
            });
            input.focus();
        },
        preConfirm: function() {
            const input = Swal.getPopup().querySelector('#two-factor-code');
            const payload = Object.assign({}, options.data, { code: input.value.trim() });

            if (!payload.code) {
                Swal.showValidationMessage('Informe o código do aplicativo ou de recuperação.');
                input.focus();
                return false;
            }

            setAppDialogBusy(true, 'Verificando…');

            return twoFactorRequest(options.url, options.type, payload).catch(function(jqXHR) {
                setAppDialogBusy(false);
                Swal.showValidationMessage(twoFactorErrorMessage(jqXHR));
                shakeAppDialog();
                input.focus();
                input.select();
                return false;
            });
        },
    });
}

/**
 * Assistente de ativação (tela /two-factor com 2FA inativo)
 */
function bindTwoFactorWizard() {
    if (!elementExists('#tf-wizard')) {
        return;
    }

    $('#tf-start').on('click', startTwoFactorSetup);

    $('[data-tf-go]').on('click', function() {
        goToTwoFactorStep(Number($(this).data('tf-go')));
    });

    $('#tf-copy-secret').on('click', function() {
        copyToClipboard($('#tf-secret').text().replace(/\s/g, ''), 'Chave copiada');
    });

    $('#tf-confirm').on('click', confirmTwoFactor);

    bindOtpInput('#tf-otp', onTwoFactorOtpChange, confirmTwoFactor);
}

function goToTwoFactorStep(step) {
    $('[data-tf-step]').addClass('d-none');
    $('[data-tf-step="' + step + '"]').removeClass('d-none');

    $('[data-tf-indicator]').each(function() {
        const indicator = Number($(this).data('tf-indicator'));

        $(this)
            .toggleClass('is-done', indicator < step)
            .toggleClass('is-current', indicator === step)
            .attr('aria-current', indicator === step ? 'step' : null);
    });

    if (step === 3) {
        focusOtp('#tf-otp');
    }
}

function startTwoFactorSetup() {
    // Reaproveita o QR já gerado: um novo setup invalidaria o que o usuário pode já ter escaneado.
    if ($('#tf-qr').children().length) {
        goToTwoFactorStep(2);
        return;
    }

    const $button = $('#tf-start').prop('disabled', true);

    twoFactorRequest('/two-factor/setup', 'POST').done(function(response) {
        $('#tf-qr').html(response.qr_code);
        $('#tf-secret').text(response.secret);
        goToTwoFactorStep(2);
    }).fail(function(jqXHR) {
        clickWarningMessage('Não foi possível concluir', twoFactorErrorMessage(jqXHR));
    }).always(function() {
        $button.prop('disabled', false);
    });
}

function onTwoFactorOtpChange(code) {
    $('#tf-confirm').prop('disabled', code.length !== 6 || twoFactorConfirming);

    if (code.length === 6) {
        confirmTwoFactor();
    }
}

function confirmTwoFactor() {
    const code = getOtpValue('#tf-otp');

    if (code.length !== 6 || twoFactorConfirming) {
        return;
    }

    twoFactorConfirming = true;
    const $button = $('#tf-confirm');
    const label = $button.html();
    $button.prop('disabled', true).html('<span class="spinner-border spinner-border-sm me-1" aria-hidden="true"></span> Verificando...');

    twoFactorRequest('/two-factor/confirm', 'POST', { code: code }).done(function(data) {
        $('#tf-status')
            .removeClass('dash-chip-warning')
            .addClass('dash-chip-success')
            .html('<i class="fa-solid fa-check" aria-hidden="true"></i> Ativa');

        renderTwoFactorRecoveryCodes(data.recovery_codes);
        goToTwoFactorStep(4);
    }).fail(function(jqXHR) {
        showOtpError('#tf-otp', twoFactorErrorMessage(jqXHR));
    }).always(function() {
        twoFactorConfirming = false;
        $button.html(label).prop('disabled', getOtpValue('#tf-otp').length !== 6);
    });
}

/**
 * Códigos de recuperação (fim do assistente e "Gerar novos")
 */
function bindTwoFactorRecoveryCodes() {
    if (!elementExists('#tf-recovery')) {
        return;
    }

    $('#tf-copy-codes').on('click', function() {
        copyToClipboard(twoFactorRecoveryCodes.join('\n'), 'Códigos copiados');
    });

    $('#tf-download-codes').on('click', downloadTwoFactorRecoveryCodes);

    $('#tf-saved-codes').on('change', function() {
        $('#tf-finish').prop('disabled', !this.checked);
    });

    $('#tf-finish').on('click', function() {
        twoFactorRecoveryCodes = [];
        window.location.reload();
    });

    // Evita sair sem guardar os códigos: eles não são exibidos novamente
    $(window).on('beforeunload', function(e) {
        if (twoFactorRecoveryCodes.length && !$('#tf-saved-codes').is(':checked')) {
            e.preventDefault();
            return '';
        }
    });
}

function renderTwoFactorRecoveryCodes(codes) {
    twoFactorRecoveryCodes = codes;

    const $list = $('#tf-recovery-list').empty();
    codes.forEach(function(code) {
        $('<li>').text(code).appendTo($list);
    });

    $('#tf-saved-codes').prop('checked', false);
    $('#tf-finish').prop('disabled', true);
}

function downloadTwoFactorRecoveryCodes() {
    const content = [
        'PSI4 - Códigos de recuperação da autenticação de 2 fatores',
        'Conta: ' + $('#tf-recovery').data('account'),
        'Gerados em: ' + new Date().toLocaleString('pt-BR'),
        '',
        'Cada código pode ser usado uma única vez.',
        '',
    ].concat(twoFactorRecoveryCodes).join('\n');

    const url = URL.createObjectURL(new Blob([content], { type: 'text/plain;charset=utf-8' }));
    const link = $('<a>').attr({ href: url, download: 'psi4-codigos-de-recuperacao.txt' }).appendTo('body');

    link[0].click();
    link.remove();
    URL.revokeObjectURL(url);
}

/**
 * Gerenciamento (tela /two-factor com 2FA ativo)
 */
function bindTwoFactorManage() {
    if (!elementExists('#tf-manage')) {
        return;
    }

    $('#tf-regenerate').on('click', regenerateRecoveryCodes);
    $('#tf-disable').on('click', disableTwoFactor);
}

function regenerateRecoveryCodes() {
    promptTwoFactorReauth({
        title: 'Novos códigos de recuperação',
        text: 'Os códigos anteriores deixarão de funcionar. Informe o código do aplicativo ou de recuperação.',
        confirmText: 'Gerar códigos',
        url: '/two-factor/recovery-codes',
        type: 'POST',
    }).then(function(result) {
        $('.wrapper').removeClass('d-none');

        if (!result.isConfirmed) {
            return;
        }

        const codes = result.value.recovery_codes;

        renderTwoFactorRecoveryCodes(codes);
        $('#tf-codes-left').removeClass('dash-chip-warning').addClass('dash-chip-muted').text(codes.length + ' restantes');
        $('#tf-regenerate').prop('disabled', true);
        $('#tf-regenerated').removeClass('d-none')[0].scrollIntoView({ behavior: 'smooth', block: 'center' });
    });
}

function disableTwoFactor() {
    promptTwoFactorReauth({
        title: 'Desativar autenticação de 2 fatores',
        text: 'Sua conta voltará a ser protegida apenas pela senha. Informe o código do aplicativo ou de recuperação para desativar.',
        confirmText: 'Desativar',
        url: '/two-factor',
        type: 'DELETE',
    }).then(function(result) {
        $('.wrapper').removeClass('d-none');

        if (!result.isConfirmed) {
            return;
        }

        successResponseJson('Tudo certo', 'A autenticação de 2 fatores foi desativada.').then(function() {
            window.location.reload();
        });
    });
}

// Senha mestre dos prontuários: configuração, troca, recuperação e nova chave de recuperação.
// Toda a criptografia acontece aqui no navegador (crypto.js); o servidor só recebe os embrulhos da chave.
$(document).ready(function() {
    if (!elementExists('#encryption-key-page')) {
        return;
    }

    $('#ek-start').on('click', () => goToEncryptionKeyStep(2));
    $('#form-store-encryption-key').on('submit', function(e) {
        e.preventDefault();
        prepareEncryptionKey(this);
    });
    $('#ek-finish').on('click', storeEncryptionKey);
    $('#ek-saved').on('change', function() {
        $('#ek-finish').prop('disabled', !this.checked);
    });

    $('#form-update-passphrase').on('submit', function(e) {
        e.preventDefault();
        updatePassphraseEncryptionKey(this);
    });
    $('#form-recover-encryption-key').on('submit', function(e) {
        e.preventDefault();
        recoverEncryptionKey(this);
    });
    $('#form-update-recovery-key').on('submit', function(e) {
        e.preventDefault();
        updateRecoveryEncryptionKey(this);
    });
    $('#ek-lock').on('click', lockMedicalRecords);

    $(document).on('click', '.ek-download', function() {
        downloadRecoveryKit($(this).data('target'));
    });
    $(document).on('click', '.ek-copy', function() {
        copyToClipboard($($(this).data('target')).text(), 'Chave copiada');
    });

    if (new URLSearchParams(window.location.search).get('mode') === 'recover' && elementExists('#ek-recover')) {
        bootstrap.Collapse.getOrCreateInstance(document.getElementById('ek-recover-body'), { toggle: false }).show();
        document.getElementById('ek-recover').scrollIntoView({ behavior: 'smooth' });
    }
});

let pendingEncryptionKey = null;

function goToEncryptionKeyStep(step) {
    $('[data-ek-step]').addClass('d-none');
    $('[data-ek-step="' + step + '"]').removeClass('d-none');
    $('[data-ek-indicator]').each(function() {
        const indicator = Number($(this).data('ek-indicator'));
        $(this).toggleClass('is-done', indicator < step).toggleClass('is-current', indicator === step);
    });
}

// Valida a senha nova + confirmação de um formulário; devolve a senha ou null (exibindo o erro no campo).
function readNewPassphrase(form, field = 'passphrase') {
    const $form = $(form);
    const passphrase = $form.find('[name="' + field + '"]').val() || '';
    const confirmation = $form.find('[name="' + field + '_confirmation"]').val() || '';

    clearFormError(form);

    if (passphrase.length < MEDICAL_CRYPTO.minPassphraseLength) {
        showFieldError(form, field, 'A senha mestre deve ter pelo menos ' + MEDICAL_CRYPTO.minPassphraseLength + ' caracteres.');
        return null;
    }

    if (passphrase !== confirmation) {
        showFieldError(form, field + '_confirmation', 'As senhas não conferem.');
        return null;
    }

    return normalizePassphrase(passphrase);
}

function showFieldError(form, field, message) {
    const $input = $(form).find('[name="' + field + '"]');
    $input.addClass('is-invalid');
    $input.after('<div class="invalid-feedback d-block">' + $('<div>').text(message).html() + '</div>');
    $input.trigger('focus');
}

async function withLoading(callback) {
    loadingAjax();

    try {
        return await callback();
    } finally {
        closeLoadingAjax();
    }
}

// Passo 2 -> 3: gera a chave dos prontuários e a chave de recuperação (ainda nada é enviado).
async function prepareEncryptionKey(form) {
    const passphrase = readNewPassphrase(form);
    if (!passphrase) return;

    try {
        pendingEncryptionKey = await withLoading(async () => {
            const raw = crypto.getRandomValues(new Uint8Array(32));
            const recoveryKey = generateRecoveryKey();
            const passphraseWrap = await wrapRecordKey(raw, passphrase);
            const recoveryWrap = await wrapRecordKey(raw, normalizeRecoveryKey(recoveryKey));

            return {
                raw: raw,
                recoveryKey: recoveryKey,
                payload: {
                    passphrase_wrapped_key: passphraseWrap.wrapped,
                    passphrase_salt: passphraseWrap.salt,
                    passphrase_iterations: passphraseWrap.iterations,
                    recovery_wrapped_key: recoveryWrap.wrapped,
                    recovery_salt: recoveryWrap.salt,
                    recovery_iterations: recoveryWrap.iterations,
                    key_check: await computeKeyCheck(raw),
                },
            };
        });
    } catch (error) {
        console.error(error);
        clickErrorMessage('Algo não deu certo', 'Seu navegador não conseguiu gerar a chave. Atualize o navegador e tente novamente.');
        return;
    }

    $('#ek-recovery-key').text(pendingEncryptionKey.recoveryKey);
    goToEncryptionKeyStep(3);
}

function storeEncryptionKey() {
    if (!pendingEncryptionKey || !$('#ek-saved').is(':checked')) return;

    sendRequestByJson('/encryption-key', 'POST', pendingEncryptionKey.payload, async function() {
        await cacheMedicalRecordKey(await importRecordKey(pendingEncryptionKey.raw));
        pendingEncryptionKey = null;

        // Já cria o par das escalas e das dinâmicas, para poder guardar sem login depois.
        await ensureScaleKeyPair().catch((error) => console.log('Error', error));

        appDialog({
            tone: 'lock',
            title: 'Prontuários protegidos',
            text: 'Sua senha mestre foi configurada. A partir de agora o conteúdo dos prontuários é criptografado no seu navegador.',
            confirmText: 'Continuar',
            allowOutsideClick: false,
        }).then(() => redirectTo($('#encryption-key-page').data('redirect') || '/medical-records'));
    });
}

async function updatePassphraseEncryptionKey(form) {
    const passphrase = readNewPassphrase(form, 'new_passphrase');
    if (!passphrase) return;

    let unlocked;
    try {
        unlocked = await withLoading(async () => unlockWithPassphrase(await fetchEncryptionKeyDetails(), $(form).find('[name="current_passphrase"]').val()));
    } catch (error) {
        showFieldError(form, 'current_passphrase', 'Senha mestre atual incorreta.');
        return;
    }

    await sendNewPassphrase(form, unlocked, passphrase, 'Senha mestre alterada.');
}

async function recoverEncryptionKey(form) {
    const passphrase = readNewPassphrase(form, 'new_passphrase');
    if (!passphrase) return;

    let unlocked;
    try {
        unlocked = await withLoading(async () => unlockWithRecoveryKey(await fetchEncryptionKeyDetails(), $(form).find('[name="recovery_key"]').val()));
    } catch (error) {
        showFieldError(form, 'recovery_key', 'Chave de recuperação incorreta.');
        return;
    }

    await sendNewPassphrase(form, unlocked, passphrase, 'Acesso recuperado. Use a nova senha mestre para abrir seus prontuários.');
}

async function sendNewPassphrase(form, unlocked, passphrase, message) {
    const wrap = await withLoading(() => wrapRecordKey(unlocked.raw, passphrase));
    const payload = {
        passphrase_wrapped_key: wrap.wrapped,
        passphrase_salt: wrap.salt,
        passphrase_iterations: wrap.iterations,
        key_check: await computeKeyCheck(unlocked.raw),
    };

    sendRequestByJson('/encryption-key/passphrase', 'PUT', payload, async function() {
        await cacheMedicalRecordKey(unlocked.key);
        form.reset();
        successResponseJson('Tudo certo', message);

        const redirect = $('#encryption-key-page').data('redirect');
        if (redirect) {
            setTimeout(() => redirectTo(redirect), 1500);
        }
    });
}

// Gera uma nova chave de recuperação; a anterior deixa de funcionar.
async function updateRecoveryEncryptionKey(form) {
    let unlocked;
    try {
        unlocked = await withLoading(async () => unlockWithPassphrase(await fetchEncryptionKeyDetails(), $(form).find('[name="current_passphrase"]').val()));
    } catch (error) {
        clearFormError(form);
        showFieldError(form, 'current_passphrase', 'Senha mestre incorreta.');
        return;
    }

    const recoveryKey = generateRecoveryKey();
    const wrap = await withLoading(() => wrapRecordKey(unlocked.raw, normalizeRecoveryKey(recoveryKey)));
    const payload = {
        recovery_wrapped_key: wrap.wrapped,
        recovery_salt: wrap.salt,
        recovery_iterations: wrap.iterations,
        key_check: await computeKeyCheck(unlocked.raw),
    };

    sendRequestByJson('/encryption-key/recovery', 'PUT', payload, function() {
        form.reset();
        clearFormError(form);
        $('#ek-new-recovery-key').text(recoveryKey);
        $('#ek-new-recovery').removeClass('d-none');
    });
}

async function lockMedicalRecords() {
    await clearMedicalRecordKey();
    successResponseJson('Prontuários bloqueados', 'Neste navegador, a senha mestre será pedida novamente para abrir os prontuários.');
}

function downloadRecoveryKit(selector) {
    const key = $(selector).text().trim();
    if (!key) return;

    const page = $('#encryption-key-page');
    const content = [
        'PSI4 - Chave de recuperação dos prontuários',
        '',
        'Conta: ' + page.data('email'),
        'Gerada em: ' + new Date().toLocaleString('pt-BR'),
        '',
        'Chave de recuperação:',
        key,
        '',
        'Use esta chave para criar uma nova senha mestre caso esqueça a atual.',
        'Guarde este arquivo em local seguro (ex.: impresso ou em um gerenciador de senhas).',
        'Sem a senha mestre e sem esta chave, ninguém (nem a equipe do PSI4) consegue abrir seus prontuários.',
    ].join('\r\n');

    const url = URL.createObjectURL(new Blob([content], { type: 'text/plain;charset=utf-8' }));
    const link = document.createElement('a');
    link.href = url;
    link.download = 'psi4-chave-de-recuperacao.txt';
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(url);
}

let paginateAccessLogsSeq = 0;

function paginateAccessLogs(callback = null) {
    if (!elementExists('#form-search') || !elementExists('[name="action"]')) return;

    const seq = ++paginateAccessLogsSeq;

    sendRequest(
        '/access-logs/paginate',
        'GET',
        '#form-search',
        'json',
        function(response) {
            // ignora respostas de buscas antigas que chegaram depois da mais recente
            if (seq !== paginateAccessLogsSeq) {
                return;
            }
            $('.list-paginate').html(response.html);
            if (isFunction(callback)) {
                callback();
            }
        }
    );
}

function clearFiltersAccessLogs() {
    $('#form-search #action').val('');
    $('#form-search #search_date').val('');
    paginateAccessLogs();
}

// Painel lateral "Acessos" das telas do prontuário (visualizar e editar).
let paginateAccessLogsPanelSeq = 0;

function initAccessLogsPanel() {
    if (!elementExists('#docAccessPanel')) return;

    initDocSidePanels();

    $('#docAccessToggle').on('click', () => toggleAccessLogsPanel());
    $('#docAccessClose').on('click', () => toggleAccessLogsPanel(false));
    $('#docAccessRefresh').on('click', () => paginateAccessLogsPanel());
    $('#docAccessAction').on('change', () => paginateAccessLogsPanel());
    $('#docAccessClear').on('click', clearFiltersAccessLogsPanel);
    $('#form-search-access-logs-panel').on('submit', function (e) {
        e.preventDefault();
        paginateAccessLogsPanel();
    });

    $('#docAccessList').on('click', '.js-page-link', function (e) {
        e.preventDefault();
        const url = $(this).attr('href');
        if (url) paginateAccessLogsPanel(url);
    });

    initDateRangePickers(() => paginateAccessLogsPanel(), true);
}

function toggleAccessLogsPanel(open) {
    const show = toggleDocSidePanel('docAccessPanel', open);

    // carrega só na primeira abertura; depois, pelo botão Atualizar ou filtros
    if (show && !$('#docAccessList').data('loaded')) {
        paginateAccessLogsPanel();
    }
}

// url: link de paginação (já traz os filtros); sem url, usa o formulário de filtros do painel.
function paginateAccessLogsPanel(url = null) {
    if (!elementExists('#docAccessList')) return;

    const seq = ++paginateAccessLogsPanelSeq;
    const list = $('#docAccessList');

    $.ajax({
        url: url || '/access-logs/paginate',
        type: 'GET',
        dataType: 'json',
        data: url ? null : $('#form-search-access-logs-panel').serialize(),
        beforeSend: function () {
            list.attr('aria-busy', 'true').html('<div class="doc-access-loading"><i class="fas fa-spinner fa-spin me-2"></i> Carregando...</div>');
        },
        success: function (response) {
            // ignora respostas de buscas antigas que chegaram depois da mais recente
            if (seq !== paginateAccessLogsPanelSeq) return;

            list.data('loaded', true).html(response.html).scrollTop(0);
        },
        error: function (jqXHR) {
            if (seq !== paginateAccessLogsPanelSeq) return;

            list.html('<div class="doc-access-empty"><p class="mb-3">Não foi possível carregar os acessos.</p>' +
                '<button type="button" class="btn btn-outline-primary btn-sm" onclick="paginateAccessLogsPanel()">Tentar novamente</button></div>');
            errorResponseJson(jqXHR);
        },
        complete: function () {
            if (seq === paginateAccessLogsPanelSeq) list.removeAttr('aria-busy');
        }
    });
}

function clearFiltersAccessLogsPanel() {
    $('#docAccessAction').val('');
    $('#docAccessDate').val('');
    paginateAccessLogsPanel();
}

